properties.tools:
[
  {
    "name": "render_diagram",
    "route": "diagram.render",
    "strict": true,
    "description": "Validate a Mermaid diagram and render it. Returns valid (true or false), the diagram code and, when valid, the rendered image. Call it before you answer, and again after fixing an invalid diagram.",
    "input_schema": {
      "type": "object",
      "properties": {
        "diagramCode": {
          "type": "string",
          "description": "the Mermaid diagram code to validate and render"
        },
        "title": {
          "type": "string",
          "description": "an optional title for the diagram"
        }
      },
      "required": [
        "diagramCode"
      ],
      "additionalProperties": false
    }
  }
]
